CREATE TABLE public.service_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, profession text NOT NULL CHECK(profession IN ('ip_valuer','lawyer','patent_agent','consultant','other')), description text NOT NULL, organization text, contact_email text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_notes text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.service_listings TO authenticated; GRANT SELECT ON public.service_listings TO anon; GRANT ALL ON public.service_listings TO service_role;
ALTER TABLE public.service_listings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.listing_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), ip_listing_id uuid UNIQUE REFERENCES public.ip_listings(id), service_listing_id uuid UNIQUE REFERENCES public.service_listings(id), published_at timestamptz NOT NULL, introductory_expires_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, period_type text NOT NULL DEFAULT 'introductory' CHECK(period_type IN ('introductory','paid')), admin_hidden boolean NOT NULL DEFAULT false, admin_notes text, updated_at timestamptz NOT NULL DEFAULT now(), CHECK((ip_listing_id IS NULL)<>(service_listing_id IS NULL)));
GRANT SELECT ON public.listing_subscriptions TO authenticated; GRANT ALL ON public.listing_subscriptions TO service_role;
ALTER TABLE public.listing_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_owner_admin_read ON public.listing_subscriptions FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.listing_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES public.listing_subscriptions(id), owner_id uuid NOT NULL REFERENCES public.profiles(id), idempotency_key uuid NOT NULL UNIQUE, amount integer NOT NULL DEFAULT 1000 CHECK(amount=1000), currency text NOT NULL DEFAULT 'KES' CHECK(currency='KES'), environment text NOT NULL DEFAULT 'sandbox' CHECK(environment IN ('sandbox','live')), phone_number text NOT NULL, status text NOT NULL DEFAULT 'initiating' CHECK(status IN ('initiating','pending','succeeded','failed','unknown')), checkout_request_id text UNIQUE, merchant_request_id text, provider_result_code text, provider_message text, confirmation_method text, confirmed_at timestamptz, applied_at timestamptz, new_expiry timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.listing_payments TO authenticated; GRANT ALL ON public.listing_payments TO service_role;
ALTER TABLE public.listing_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_owner_admin_read ON public.listing_payments FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_open_listing_payment ON public.listing_payments(subscription_id) WHERE status IN ('initiating','pending','unknown');
CREATE TABLE public.listing_visibility_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES public.listing_subscriptions(id), owner_id uuid NOT NULL, event_key text NOT NULL UNIQUE, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.listing_visibility_events TO authenticated; GRANT ALL ON public.listing_visibility_events TO service_role;
ALTER TABLE public.listing_visibility_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY visibility_events_read ON public.listing_visibility_events FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.listing_has_visibility(p_ip uuid DEFAULT NULL,p_service uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.listing_subscriptions s WHERE ((p_ip IS NOT NULL AND s.ip_listing_id=p_ip) OR (p_service IS NOT NULL AND s.service_listing_id=p_service)) AND s.expires_at>now() AND NOT s.admin_hidden) $$;
REVOKE ALL ON FUNCTION public.listing_has_visibility(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.listing_has_visibility(uuid,uuid) TO anon,authenticated,service_role;
ALTER POLICY "Active listings viewable by everyone" ON public.ip_listings USING(status='active' AND verification_status='verified' AND public.listing_has_visibility(id,NULL));
REVOKE DELETE ON public.ip_listings FROM authenticated;
CREATE POLICY service_public_read ON public.service_listings FOR SELECT TO anon,authenticated USING(status='approved' AND public.listing_has_visibility(NULL,id));
CREATE POLICY service_owner_admin_read ON public.service_listings FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY service_owner_submit ON public.service_listings FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND status='pending' AND reviewed_by IS NULL AND reviewed_at IS NULL AND review_notes IS NULL AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.kyc_status='approved'));
CREATE OR REPLACE FUNCTION public.start_listing_visibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE stamp timestamptz:=now(); finish timestamptz; BEGIN finish:=((stamp AT TIME ZONE 'Africa/Nairobi')+interval '3 months') AT TIME ZONE 'Africa/Nairobi'; IF TG_TABLE_NAME='ip_listings' THEN IF NEW.status='active' AND NEW.verification_status='verified' THEN INSERT INTO public.listing_subscriptions(owner_id,ip_listing_id,published_at,introductory_expires_at,expires_at) VALUES(NEW.owner_id,NEW.id,stamp,finish,finish) ON CONFLICT(ip_listing_id) DO NOTHING; END IF; ELSE IF NEW.status='approved' THEN INSERT INTO public.listing_subscriptions(owner_id,service_listing_id,published_at,introductory_expires_at,expires_at) VALUES(NEW.owner_id,NEW.id,stamp,finish,finish) ON CONFLICT(service_listing_id) DO NOTHING; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER start_ip_visibility AFTER INSERT OR UPDATE ON public.ip_listings FOR EACH ROW EXECUTE FUNCTION public.start_listing_visibility();
CREATE TRIGGER start_service_visibility AFTER INSERT OR UPDATE ON public.service_listings FOR EACH ROW EXECUTE FUNCTION public.start_listing_visibility();
INSERT INTO public.listing_subscriptions(owner_id,ip_listing_id,published_at,introductory_expires_at,expires_at) SELECT owner_id,id,coalesce(verified_at,created_at),((coalesce(verified_at,created_at) AT TIME ZONE 'Africa/Nairobi')+interval '3 months') AT TIME ZONE 'Africa/Nairobi',((coalesce(verified_at,created_at) AT TIME ZONE 'Africa/Nairobi')+interval '3 months') AT TIME ZONE 'Africa/Nairobi' FROM public.ip_listings WHERE status='active' AND verification_status='verified' ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.review_service_listing(p_id uuid,p_approve boolean,p_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.service_listings; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator MFA required'; END IF; IF length(trim(coalesce(p_notes,'')))<3 THEN RAISE EXCEPTION 'Review notes required'; END IF; SELECT * INTO r FROM public.service_listings WHERE id=p_id FOR UPDATE; IF r.id IS NULL OR r.owner_id=auth.uid() THEN RAISE EXCEPTION 'Invalid request or self review'; END IF; IF r.status<>'pending' THEN RAISE EXCEPTION 'Listing already reviewed'; END IF; IF p_approve AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=r.owner_id AND kyc_status='approved') THEN RAISE EXCEPTION 'Identity approval required'; END IF; UPDATE public.service_listings SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,review_notes=p_notes,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=p_id; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(),'service.review','service_listing',p_id,jsonb_build_object('approved',p_approve,'notes',p_notes)); INSERT INTO public.notifications(user_id,kind,title,body) VALUES(r.owner_id,'service_review','Service listing reviewed',CASE WHEN p_approve THEN 'Approved. Your three-month introductory visibility has started.' ELSE 'Not approved: '||p_notes END); END $$;
REVOKE ALL ON FUNCTION public.review_service_listing(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_service_listing(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.manage_listing_visibility(p_id uuid,p_hidden boolean,p_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.listing_subscriptions; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator MFA required'; END IF; IF length(trim(coalesce(p_notes,'')))<3 THEN RAISE EXCEPTION 'Notes required'; END IF; SELECT * INTO s FROM public.listing_subscriptions WHERE id=p_id FOR UPDATE; IF s.id IS NULL THEN RAISE EXCEPTION 'Subscription not found'; END IF; UPDATE public.listing_subscriptions SET admin_hidden=p_hidden,admin_notes=p_notes,updated_at=now() WHERE id=p_id; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(),'listing.visibility','listing_subscription',p_id,jsonb_build_object('hidden',p_hidden,'notes',p_notes)); INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(s.owner_id,'listing_visibility','Listing visibility updated',p_notes,s.ip_listing_id); END $$;
REVOKE ALL ON FUNCTION public.manage_listing_visibility(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_listing_visibility(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.apply_verified_listing_payment(p_id uuid,p_confirmed_at timestamptz,p_code text,p_message text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.listing_payments; s public.listing_subscriptions; finish timestamptz; BEGIN SELECT * INTO p FROM public.listing_payments WHERE id=p_id FOR UPDATE; IF p.id IS NULL OR p.checkout_request_id IS NULL OR p_code<>'0' THEN RAISE EXCEPTION 'A verified provider checkout is required'; END IF; IF p.applied_at IS NOT NULL THEN RETURN p.new_expiry; END IF; IF p.environment<>'live' THEN UPDATE public.listing_payments SET status='succeeded',provider_result_code=p_code,provider_message=p_message,confirmation_method='stk_query',confirmed_at=p_confirmed_at,updated_at=now() WHERE id=p_id; RETURN NULL; END IF; SELECT * INTO s FROM public.listing_subscriptions WHERE id=p.subscription_id FOR UPDATE; finish:=greatest(s.expires_at,p_confirmed_at)+interval '30 days'; UPDATE public.listing_subscriptions SET expires_at=finish,period_type='paid',updated_at=now() WHERE id=s.id; UPDATE public.listing_payments SET status='succeeded',provider_result_code=p_code,provider_message=p_message,confirmation_method='stk_query',confirmed_at=p_confirmed_at,applied_at=now(),new_expiry=finish,updated_at=now() WHERE id=p_id; INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(s.owner_id,'listing_payment','M-Pesa renewal confirmed','KSh 1,000 received. Visibility renewed for 30 days until '||(finish AT TIME ZONE 'Africa/Nairobi')::text,s.ip_listing_id); INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(p.owner_id,'listing.payment_verified','listing_payment',p.id,jsonb_build_object('amount',1000,'expires_at',finish,'confirmation','stk_query')); RETURN finish; END $$;
REVOKE ALL ON FUNCTION public.apply_verified_listing_payment(uuid,timestamptz,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_verified_listing_payment(uuid,timestamptz,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.process_listing_visibility_notifications() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.listing_subscriptions; days_left integer; kind text; event text; inserted uuid; n integer:=0; BEGIN FOR s IN SELECT * FROM public.listing_subscriptions WHERE expires_at<now()+interval '15 days' ORDER BY updated_at LIMIT 500 LOOP days_left:=(s.expires_at AT TIME ZONE 'Africa/Nairobi')::date-(now() AT TIME ZONE 'Africa/Nairobi')::date; kind:=CASE WHEN s.expires_at<=now() THEN 'suspended' WHEN s.period_type='introductory' AND days_left IN (14,7,3) THEN 'reminder_'||days_left WHEN s.period_type='paid' AND days_left IN (7,3) THEN 'reminder_'||days_left END; IF kind IS NOT NULL THEN event:=s.id::text||':'||s.expires_at::text||':'||kind; INSERT INTO public.listing_visibility_events(subscription_id,owner_id,event_key,kind) VALUES(s.id,s.owner_id,event,kind) ON CONFLICT(event_key) DO NOTHING RETURNING id INTO inserted; IF inserted IS NOT NULL THEN INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(s.owner_id,'listing_visibility',CASE WHEN kind='suspended' THEN 'Listing visibility suspended' ELSE 'Listing renewal due in '||days_left||' days' END,'Renew this listing for KSh 1,000 / 30 days from your dashboard. Your listing and documents have not been deleted.',s.ip_listing_id); n:=n+1; END IF; END IF; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.process_listing_visibility_notifications() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.process_listing_visibility_notifications() TO service_role;
CREATE OR REPLACE FUNCTION public.review_ip_verification(p_id uuid,p_decision text,p_notes text,p_confirmation_url text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ip_verification_requests; v public.ip_verification_results; next_status text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator MFA required'; END IF; IF p_decision NOT IN ('approve','reject','needs_documents','kipi_confirmation','inconclusive','reopen') OR length(trim(coalesce(p_notes,'')))<3 THEN RAISE EXCEPTION 'Valid decision and notes required'; END IF; SELECT * INTO r FROM public.ip_verification_requests WHERE id=p_id FOR UPDATE; IF r.id IS NULL OR r.user_id=auth.uid() THEN RAISE EXCEPTION 'Invalid request or self review'; END IF; IF r.submission_status='processing' THEN RAISE EXCEPTION 'Processing must finish'; END IF; SELECT * INTO v FROM public.ip_verification_results WHERE verification_request_id=p_id ORDER BY generated_at DESC LIMIT 1; next_status:=CASE p_decision WHEN 'reject' THEN 'DISCREPANCY_DETECTED' WHEN 'approve' THEN 'PARTIALLY_VERIFIED' ELSE 'MANUAL_REVIEW_REQUIRED' END; IF p_decision='approve' AND (v.id IS NULL OR NOT v.record_match OR v.result_status IN ('DISCREPANCY_DETECTED','MANUAL_REVIEW_REQUIRED')) THEN RAISE EXCEPTION 'Resolve uncertain or conflicting evidence before approving'; END IF; IF p_confirmation_url IS NOT NULL THEN RAISE EXCEPTION 'A website link alone cannot authenticate a certificate or prove current ownership'; END IF; UPDATE public.ip_verification_requests SET verification_status=next_status,administrator_decision=CASE WHEN p_decision='reopen' THEN NULL ELSE p_decision END,administrator_notes=trim(p_notes),official_confirmation_url=NULL,submission_status=CASE WHEN p_decision='reopen' THEN 'submitted' ELSE 'reviewed' END,lease_until=NULL,updated_at=now() WHERE id=p_id; INSERT INTO public.ip_verification_reviews(verification_request_id,administrator_id,previous_status,new_status,review_decision,review_notes) VALUES(p_id,auth.uid(),r.verification_status,next_status,p_decision,trim(p_notes)); INSERT INTO public.ip_verification_audit_logs(verification_request_id,actor_id,action,details) VALUES(p_id,auth.uid(),'verification.review_'||p_decision,jsonb_build_object('notes',p_notes)); INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(),'verification.review_'||p_decision,'ip_verification',p_id,jsonb_build_object('notes',p_notes,'previous',r.verification_status,'result',next_status)); INSERT INTO public.notifications(user_id,kind,title,body,listing_id) VALUES(r.user_id,'ip_verification','IP verification: '||replace(p_decision,'_',' '),p_notes,r.listing_id); END $$;